import pytest
from pydantic import ValidationError

from app.schemas.ai import EscalateRequest


VALID_CASES = [{'reason': 'r'}, {'reason': 'rr'}, {'reason': 'rrrrr'}, {'reason': 'rrrrrrrrrr'}, {'reason': 'rrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrr'}, {'reason': 'rrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrr'}, {'reason': ''}, {'reason': ''}]
INVALID_CASES = [{'reason': ''}, {'reason': ''}, {'reason': ''}, {'reason': ''}, {'reason': ''}, {'reason': ''}, {'reason': ''}, {'reason': ''}]


@pytest.mark.parametrize("payload", VALID_CASES)
def test_ai_escalate_request_bulk_unit_valid_bulk(payload) -> None:
    model = EscalateRequest(**payload)
    assert isinstance(model, EscalateRequest)


@pytest.mark.parametrize("payload", INVALID_CASES)
def test_ai_escalate_request_bulk_unit_invalid_bulk(payload) -> None:
    with pytest.raises(ValidationError):
        EscalateRequest(**payload)
